import { buildAvatarFileHref } from "@/lib/file-links";
import type { AdminProfile } from "@/types/profile";

function buildAdminBase(user: AdminProfile) {
  return {
    id: user.id,
    email: "",
    role: "admin" as const,
    plan: user.plan,
    displayName: user.displayName,
    nombre: user.nombre,
    rol: user.rol,
    tipoRegistro: "admin" as const,
    ubicacion: user.ubicacion ?? undefined,
    permissions: [...(user.permissions ?? [])],
  };
}

export function sanitizeAdminForClient(user: AdminProfile): AdminProfile {
  return {
    ...buildAdminBase(user),
    avatar: user.avatarAssetPublicId ? buildAvatarFileHref(user.avatarAssetPublicId) : user.avatar ?? undefined,
  };
}

export function sanitizeOwnAdminForClient(user: AdminProfile): AdminProfile {
  return {
    ...sanitizeAdminForClient(user),
    telefono: user.telefono ?? undefined,
    website: user.website ?? undefined,
  };
}
